function requireSignIn(){if(security.current.authRequired)return;security.current.authRequired=true;++accessEpoch.current;flushSync(()=>{clearPrivateState();setLocked(false);setAuthRequired(true);setLoading(false);});window.dispatchEvent(new Event('dolgi-auth-required'));}
function lockDevice(){if(security.current.locked||security.current.authRequired)return;security.current.locked=true;++accessEpoch.current;flushSync(()=>{clearPrivateState();setLocked(true);setLoading(false);});lockRequest.current=fetch('/api/data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:'lock'}),keepalive:true}).then(r=>{if(r.status===401)requireSignIn();}).catch(()=>{});}
function apply(data:any){if(data.locked){security.current.locked=true;setPinEnabled(true);clearPrivateState();setLocked(true);return;}if(data.accountId){if(account.current&&account.current!==data.accountId)clearPrivateState();account.current=data.accountId;}latest.current={s:data.state,revision:data.revision,locked:false};security.current={pinEnabled:data.pinEnabled,locked:false,authRequired:false};setS(data.state);setRevision(data.revision);setPinEnabled(data.pinEnabled);setLocked(false);setCategory(c=>data.state.categories.some((x:any)=>x.id===c)?c:data.state.categories[0]?.id||'');}
async function load(){if(security.current.authRequired)return;const epoch=accessEpoch.current;setError('');setLoading(true);try{const r=await fetch('/api/data',{cache:'no-store'});const d:any=await r.json();if(epoch!==accessEpoch.current)return;if(r.status===401){requireSignIn();return;}if(r.status===423){flushSync(()=>apply(d));return;}if(!r.ok)throw Error(d.error);flushSync(()=>apply(d));}catch(e:any){if(epoch===accessEpoch.current)flushSync(()=>{clearPrivateState();setError(e.message||'Не удалось проверить доступ.');});}finally{if(epoch===accessEpoch.current)setLoading(false);}}
async function mutate(a:any,message='Сохранено'){if(a.type==='lock'){lockDevice();return true;}if(pending.current||security.current.authRequired||document.hidden)return false;const epoch=accessEpoch.current;pending.current=true;setBusy(true);setError('');try{if(a.type==='unlock')await lockRequest.current;if(epoch!==accessEpoch.current)return false;const r=await fetch('/api/data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...a,revision:latest.current.revision})});const d:any=await r.json();if(epoch!==accessEpoch.current)return false;if(r.status===401){requireSignIn();return false;}if(r.status===423){apply(d);throw Error('Введите PIN для продолжения');}if(!r.ok)throw Error(d.error);apply(d);if(a.type==='unlock')window.dispatchEvent(new Event('dolgi-unlocked'));if(message)setToast(message);return true;}catch(e:any){if(epoch===accessEpoch.current)setError(e.message);return false;}finally{pending.current=false;setBusy(false);}}
async function checkActivity(){if(security.current.locked||security.current.authRequired||pending.current||Date.now()-lastCheck.current<60000)return;lastCheck.current=Date.now();const epoch=accessEpoch.current;try{const r=await fetch('/api/data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:'activity'}),cache:'no-store'});const d:any=await r.json();if(epoch!==accessEpoch.current)return;if(r.status===401){requireSignIn();return;}if(r.status===423){lockDevice();return;}if(r.ok&&account.current&&d.accountId!==account.current){++accessEpoch.current;flushSync(clearPrivateState);await load();}}catch{/* A failed renewal never extends the server-side expiry. */}}
useEffect(()=>{load();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});},[]);
useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),3000);return()=>clearTimeout(t);}},[toast]);
useEffect(()=>{
let stopped=false,running=false;
const sync=async()=>{
if(stopped||running||document.hidden||pending.current||security.current.locked||security.current.authRequired)return;
running=true;const epoch=accessEpoch.current,revision=latest.current.revision;
try{const r=await fetch('/api/data',{cache:'no-store'}),d:any=await r.json();
if(stopped||document.hidden||epoch!==accessEpoch.current||pending.current||latest.current.revision!==revision)return;
if(r.status===401){requireSignIn();return;}if(r.status===423){apply(d);return;}
if(!r.ok)throw Error();
if(account.current&&d.accountId!==account.current){requireSignIn();return;}
if(d.revision!==revision||d.pinEnabled!==security.current.pinEnabled)apply(d);
}catch{if(!stopped&&!document.hidden&&!security.current.locked&&!security.current.authRequired)setError('Нет связи с облаком. Последние загруженные данные показаны; новые изменения пока не синхронизированы.');}
finally{running=false;}
};
const timer=setInterval(sync,15000);window.addEventListener('online',sync);
return()=>{stopped=true;clearInterval(timer);window.removeEventListener('online',sync);};
},[]);
useEffect(()=>installPrivacyLifecycle({window,document,shouldExpire:()=>security.current.pinEnabled,expire:()=>{lockDevice();},suspend:()=>{setHidden(true);if(security.current.pinEnabled)lockDevice();},resume:async()=>{await lockRequest.current;if(!security.current.locked&&!security.current.authRequired)await load();flushSync(()=>setHidden(false));},activity:()=>{void checkActivity();}}),[]);
useEffect(()=>{const c=(document as any).modelContext;if(!c?.registerTool)return;const ac=new AbortController();const tools=[{name:'search_debts',description:'Search the current signed-in user’s debts by person, amount, currency, purpose, comment or tags.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute:async(input:any)=>{if(latest.current.locked)throw Error('Application locked');if(typeof input.query!=='string'||input.query.length>200)throw Error('Invalid query');const f={...defaults,search:input.query};setFilters(f);setTab('debts');return filterDebts(latest.current.s,f).map(d=>({id:d.id,currency:d.currency,remaining:remaining(latest.current.s,d)/100,purpose:d.purpose}));}},{name:'start_debt_creation',description:'Open the new debt form. Does not save a debt.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:async(input:any)=>{if(latest.current.locked)throw Error('Application locked');if(!input||Object.keys(input).length)throw Error('No arguments expected');setTab('add');return {opened:true};}}];for(const t of tools)Promise.resolve(c.registerTool(t,{signal:ac.signal})).catch(()=>{});return()=>ac.abort();},[]);
