function key(k:string){setAmount(v=>{if(k==='C')return '';if(k==='back')return v.slice(0,-1);if(k==='.')return v.includes('.')?v:(v||'0')+'.';const n=(v+k).replace(/^0+(?=\d)/,'');if(n.split('.')[0].length>11||(n.split('.')[1]?.length||0)>2)return v;return n;});}
async function saveDebt(){if(await mutate({type:'debt',direction,personId,personName,amount,currency,date,due,purpose,comment,categoryId:category,tags:tags.split(',').map(t=>t.trim()).filter(Boolean),reminderDays},'Долг записан')){choosePerson(null);setAmount('');setPurpose('');setComment('');setDate(today());setDue('');setTags('');setReminderDays([]);setDetails(false);}}
const debt=s.debts.find(d=>d.id===debtId),person=s.people.find(p=>p.id===personDetail),getName=(id:string)=>s.people.find(p=>p.id===id)?.name||'Человек';
