function exportCSV(){const cell=(v:any)=>'"'+String(v??'').replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"';const rows=[['Тип','Человек','Направление','Валюта','Сумма','Возвращено','Взаимозачет','Осталось','Дата','Срок','Назначение','Комментарий','Категория','Теги','ID','Связанная операция'],...s.debts.map(d=>['Долг',getName(d.personId),d.direction==='in'?'Мне должны':'Я должен',d.currency,d.amount/100,s.transactions.filter(t=>t.debtId===d.id&&t.kind==='return').reduce((v,t)=>v+t.amount,0)/100,s.transactions.filter(t=>t.debtId===d.id&&t.kind==='setoff').reduce((v,t)=>v+t.amount,0)/100,remaining(s,d)/100,d.date,d.due,d.purpose,d.comment,s.categories.find(c=>c.id===d.categoryId)?.name,d.tags.join(', '),d.id,'']),...s.transactions.map(t=>{const d=s.debts.find(d=>d.id===t.debtId)!;return [t.kind==='return'?'Возврат':'Взаимозачет',getName(d.personId),d.direction,d.currency,t.amount/100,'','','',t.date,'','',t.comment,'','',t.id,t.debtId+' / '+t.groupId];}),...s.notes.map(n=>['История: '+n.kind,getName(n.personId),'','','','','','',n.date,'','',n.text,'','',n.id,n.debtId])];saveFile('Долги-'+today()+'.csv','\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');setToast('CSV выгружен — можно открыть в Excel или Numbers');}
function exportCalendar(){const esc=(v:string)=>v.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Dolgi//RU','CALSCALE:GREGORIAN'];for(const d of active.filter(d=>d.due)){lines.push('BEGIN:VEVENT','UID:'+d.id+'@dolgi','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART:'+d.due.replace(/-/g,'')+'T060000Z','DTEND:'+d.due.replace(/-/g,'')+'T061500Z','SUMMARY:'+esc((d.direction==='in'?getName(d.personId)+' должен вам':'Вернуть: '+getName(d.personId))+' '+fmt(remaining(s,d),d.currency)),'DESCRIPTION:'+esc(d.purpose+'\n'+d.comment));for(const r of s.reminders.filter(r=>r.debtId===d.id))lines.push('BEGIN:VALARM','ACTION:DISPLAY','DESCRIPTION:Напоминание о долге','TRIGGER:'+(r.days<0?'P1D':r.days===0?'PT0M':'-P'+r.days+'D'),'END:VALARM');lines.push('END:VEVENT');}lines.push('END:VCALENDAR');saveFile('Долги-напоминания.ics',lines.join('\r\n'),'text/calendar;charset=utf-8');setToast('Откройте файл в календаре для напоминаний');}
function DebtCard({d}:{d:Debt}){const r=remaining(s,d),late=r>0&&d.due&&d.due<today();return <button className="debt-card" onClick={()=>setDebtId(d.id)}><div className="card-top"><span className={'direction-icon '+d.direction}><IconDir dir={d.direction}/></span><span className="card-person">{getName(d.personId)}<small>{d.direction==='in'?'Мне должен':'Я должен'}</small></span><span className={'currency-mark '+d.currency.toLowerCase()}>{d.currency}</span><ChevronRight size={18}/></div><strong className="card-amount">{fmt(r,d.currency)}</strong><p>{d.purpose||'Без назначения'}</p><div className="card-foot"><span className={late?'late':''}>{r===0?<><Check size={14}/> Закрыт</>:late?<><Clock3 size={14}/> Просрочено {Math.abs(dayDiff(d.due))} дн.</>:<><CalendarDays size={14}/>{d.due?'до '+dateText(d.due):'Без срока'}</>}</span>{r>0&&r<d.amount&&<span>{s.transactions.some(t=>t.debtId===d.id&&t.kind==='return')?'Частичный возврат':'Взаимозачет'}</span>}</div>{r>0&&r<d.amount&&<div className="progress"><i style={{width:(1-r/d.amount)*100+'%'}}/></div>}</button>}
function Timeline({ds,pid}:{ds:Debt[],pid?:string}){
const ids=new Set(ds.map(d=>d.id)), owner=pid||ds[0]?.personId;
const monetary=(settlements.events.get(owner)||[]).filter(e=>e.movements.some(m=>ids.has(m.debtId))).map(e=>{
const amount=e.kind==='setoff'&&!pid?e.movements.filter(m=>ids.has(m.debtId)).reduce((n,m)=>n-m.incoming-m.outgoing,0):e.amount;
return {id:e.id,date:e.date,createdAt:e.createdAt,order:e.order,title:(e.kind==='debt'?(e.direction==='in'?'Вы дали ':'Вы взяли '):e.kind==='setoff'?'Взаимозачёт ':e.direction==='in'?'Вам вернули ':'Вы вернули ')+fmt(amount,e.currency),text:e.text,money:e};
});
const events=[...monetary,...s.notes.filter(n=>ids.has(n.debtId)||pid&&n.personId===pid&&!n.debtId).map(n=>({...n,id:'note:'+n.id,order:Number.MAX_SAFE_INTEGER,title:n.kind==='note'?'Заметка':n.kind==='due'?'Перенос срока':'Изменение записи',money:null}))].sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt)||b.order-a.order||b.id.localeCompare(a.id));
return <div className="timeline">{events.map(e=><article key={e.id}><span className="time-dot"/><small>{dateText(e.date)} {e.date.slice(0,4)}</small><h4>{e.title}</h4>{e.text&&<p>{e.text}</p>}{e.money&&<div className="timeline-position"><span>По всем расчётам{!pid?' с '+getName(owner):''} · {e.money.currency}</span><p>Было: {positionText(e.money.before.net,e.money.currency)}</p><strong className={positionTone(e.money.after.net)}>Стало: {positionText(e.money.after.net,e.money.currency)}</strong>{e.money.kind==='setoff'&&<small>Оба долга уменьшились. Чистая позиция не изменилась.</small>}</div>}</article>)}</div>;
}
async function submitModal(){if(!modal)return;let a:any;switch(modal.type){case 'person':a={type:'person',name:mText};break;case 'return':a={type:'return',id:modal.id,amount:mAmount,date:mDate,comment:mText};break;case 'note':a={type:'note',id:modal.id,personId:modal.personId,text:mText,date:mDate};break;case 'due':a={type:'due',id:modal.id,due:mDate};break;case 'category':a={type:'category',id:modal.id,name:mText};break;case 'filter':a={type:'filter',name:mText,value:filters};break;case 'pin':a={type:'pin',pin:mText};break;case 'edit':a={type:'edit',id:modal.id,purpose:mPurpose,comment:mText};break;}if(await mutate(a)){setModal(null);}}
